-- Generated by dbt/scripts/generate_governed_models.py from the governed T-SQL; do not edit by hand.
-- Source: sql/analysis/10_analytical_views.sql
{{ config(materialized='view') }}

SELECT
  COALESCE(i.retail_week_key, s.retail_week_key) AS retail_week_key,
  COALESCE(i.store_key, s.store_key) AS store_key,
  COALESCE(i.product_key, s.product_key) AS product_key,
  CASE WHEN i.product_key IS NULL THEN 0 ELSE 1 END AS is_ranged,
  i.opening_stock,
  i.received_qty,
  i.sold_qty AS stock_system_sold_qty,
  i.adjustment_qty,
  i.closing_stock,
  i.is_in_stock,
  COALESCE(s.sales_lines, 0) AS sales_lines,
  COALESCE(s.units_sold, 0) AS units_sold,
  COALESCE(s.sales_revenue, 0) AS sales_revenue,
  COALESCE(s.discount_value, 0) AS discount_value,
  COALESCE(s.promo_units_sold, 0) AS promo_units_sold
FROM (
  SELECT
    retail_week_key,
    store_key,
    product_key,
    opening_stock,
    received_qty,
    sold_qty,
    adjustment_qty,
    closing_stock,
    is_in_stock
  FROM {{ ref('fact_inventory') }}
) AS i
FULL OUTER JOIN (
  SELECT
    d.retail_week_key,
    f.store_key,
    f.product_key,
    COUNT(*) AS sales_lines,
    SUM(CAST(f.quantity AS INT)) AS units_sold,
    SUM(f.sales_revenue) AS sales_revenue,
    SUM(f.discount_amount) AS discount_value,
    SUM(CASE WHEN f.is_promoted = 1 THEN CAST(f.quantity AS INT) ELSE 0 END) AS promo_units_sold
  FROM {{ ref('fact_sales') }} AS f
  JOIN {{ ref('dim_date') }} AS d
    ON d.date_key = f.date_key
  GROUP BY
    d.retail_week_key,
    f.store_key,
    f.product_key
) AS s
  ON s.retail_week_key = i.retail_week_key
  AND s.store_key = i.store_key
  AND s.product_key = i.product_key
